// Bundles src/yamlEdit.ts (and the `yaml` package it uses) into one browser script for the IntelliJ
// plugin's webviews, which have no module loader: it defines `window.ecYamlEdit`. The output is
// committed (the Gradle build has no Node); test/yamlEdit.test.cjs fails when it is out of date.
//
//   npm run bundle-intellij
const path = require("path");
const esbuild = require("esbuild");

const root = path.resolve(__dirname, "..");
const outfile = path.resolve(root, "..", "intellij-eventconductor/src/main/resources/webview/ec-yaml-edit.js");

const options = {
  entryPoints: [path.join(root, "src/yamlEdit.ts")],
  bundle: true,
  format: "iife",
  globalName: "ecYamlEdit",
  platform: "browser",
  target: "es2020",
  minify: true,
  legalComments: "eof",
  banner: { js: "// Generated by plugins/vscode-eventconductor: npm run bundle-intellij. Do not edit." },
  logLevel: "silent",
};

module.exports = { options, outfile };

if (require.main === module) {
  esbuild.buildSync({ ...options, outfile });
  console.log("wrote " + path.relative(process.cwd(), outfile));
}
